import sympy
from sympy import gcd, S
from sympy.combinatorics import SymmetricGroup, AlternatingGroup, DihedralGroup, CyclicGroup
from sympy.matrices import eye, zeros

# Top-level setup
S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
V4 = AlternatingGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: R is a commutative ring",
    "H_2: I is a principal ideal of R generated by an element a",
    "¬Q: The product ideal IJ is not a principal ideal generated by ab"
]

N_HYP = 2
NEG_Q_INDEX = 2

def ideal_gen(gens):
    """
    Computes a canonical generator for the ideal generated by `gens`
    in a principal ideal domain (like Z or Q[x]) using the GCD.
    """
    if not gens:
        return S.Zero
    g = gens[0]
    for x in gens[1:]:
        g = gcd(g, x)
    # gcd(g, g) normalizes the generator (e.g., makes it positive in Z, monic in Q[x])
    return gcd(g, g)

def conditions(witness):
    """
    Checks if the witness is a valid counterexample.
    Expected witness formats:
      - dict with keys 'a', 'b', 'I' (or 'I_gens'), 'J' (or 'J_gens')
      - tuple of 5 elements: (R, I_gens, a, J_gens, b)
      - tuple of 4 elements: (I_gens, a, J_gens, b) or (a, I_gens, b, J_gens)
    """
    try:
        if isinstance(witness, dict):
            a = witness.get('a')
            b = witness.get('b')
            I_gens = witness.get('I', witness.get('I_gens', [a]))
            J_gens = witness.get('J', witness.get('J_gens', []))
        elif isinstance(witness, (tuple, list)):
            if len(witness) == 5:
                _, I_gens, a, J_gens, b = witness
            elif len(witness) == 4:
                if isinstance(witness[0], (list, tuple, set)):
                    I_gens, a, J_gens, b = witness
                else:
                    a, I_gens, b, J_gens = witness
            else:
                return [False, False, False]
        else:
            return [False, False, False]
            
        I_gens = list(I_gens)
        J_gens = list(J_gens)
    except Exception:
        return [False, False, False]
    
    # H1: R is a commutative ring
    try:
        elements = [a, b] + I_gens + J_gens
        h1 = True
        for e in elements:
            if hasattr(e, 'is_commutative'):
                if e.is_commutative is False:
                    h1 = False
                    break
            elif not isinstance(e, (int, float, complex)):
                h1 = False
                break
    except Exception:
        h1 = False

    # H2: I is a principal ideal of R generated by an element a
    try:
        gen_I = ideal_gen(I_gens)
        gen_a = ideal_gen([a])
        h2 = (sympy.simplify(gen_I - gen_a) == 0)
    except Exception:
        h2 = False

    # neg_Q: The product ideal IJ is NOT a principal ideal generated by ab
    try:
        IJ_gens = [x * y for x in I_gens for y in J_gens]
        gen_IJ = ideal_gen(IJ_gens)
        gen_ab = ideal_gen([a * b])
        q = (sympy.simplify(gen_IJ - gen_ab) == 0)
        neg_q = not q
    except Exception:
        neg_q = False

    return [bool(h1), bool(h2), bool(neg_q)]